_BASE_AGENT = _BASE_NS["agent"]
_OPERATOR = _OP_NS['sell_impact_reorder']
_OPERATOR_CONFIGURATION = {'sell_impact_demand_alpha': 0.25}

def _find_tape_hooks(namespace):
    seen = set()
    while isinstance(namespace, dict) and id(namespace) not in seen:
        seen.add(id(namespace))
        selector = namespace.get("_selected_tape")
        impl = namespace.get("_IMPL")
        if callable(selector) or impl is not None:
            return selector, impl
        namespace = namespace.get("_BASE_NS")
    return None, None

_PARENT_TAPE_SELECTOR, _PARENT_IMPL = _find_tape_hooks(_BASE_NS)

def _selected_tape(observation):
    if callable(_PARENT_TAPE_SELECTOR):
        return _PARENT_TAPE_SELECTOR(observation)
    if _PARENT_IMPL is None:
        return None
    try:
        player = int(observation.get("player", 0))
        step = int(observation.get("step", 0))
        native = _PARENT_IMPL.chassis.players[player]
        route = 2 if step >= 648 else native.get("route", 0)
        return SimpleNamespace(
            route_id=f"local-best-native-{route}",
            actions=tuple(_PARENT_IMPL.chassis.routes[route]),
        )
    except Exception:
        return None

def agent(observation, configuration=None):
    action = _BASE_AGENT(observation, configuration)
    tape = (_selected_tape(observation)
            if 'sell_impact_reorder' in {"market_queue_lockstep", "racegate_reservation",
                                  "opponent_front_run", "adaptive_market_tape_guard",
                                  "sale_advance", "sale_advance_policy",
                                  "sale_advance_pressure", "budget_guard",
                                  "room_guard", "supply_prefetch",
                                  "sell_impact_reorder"}
            else None)
    return _OPERATOR(observation, action, _OPERATOR_CONFIGURATION, tape)
# c358: compose Local Best's public market stack with V54's exact one-tile
# Productive Idle Workers opening.  Both source lineages and notices remain
# above.  This wrapper is original integration code by Taeyang/Codex, 2026.
import copy as _c358_copy

_C358_ENABLED = True
_C358_PARENT = agent
_C358_STATE = {}
_C358_REPORT = {}


def _c358_find_impl(namespace):
    seen = set()
    while isinstance(namespace, dict) and id(namespace) not in seen:
        seen.add(id(namespace))
        impl = namespace.get("_IMPL")
        if impl is not None:
            return impl
        namespace = namespace.get("_BASE_NS")
    return None


_C358_IMPL = _c358_find_impl(globals())
if _C358_ENABLED and _C358_IMPL is None:
    raise RuntimeError("c358 could not locate the native tape chassis")
_C358_RAW = (_c358_copy.deepcopy(_C358_IMPL.chassis.routes[0][:96])
             if _C358_IMPL is not None else None)


def _c358_install():
    tape = _C358_IMPL.chassis.routes[0]
    tape[:96] = _c358_copy.deepcopy(_C358_RAW)
    tape[0]["market"] = list(tape[0]["market"]) + [["BUY_SEED", "WHEAT", 1]]
    for step, command in {
        2: ["WEST"], 3: ["WEST"], 4: ["WEST"],
        5: ["PLANT", "WHEAT"], 6: ["WATER"],
    }.items():
        if tape[step]["hands"][1] != ["PASS"]:
            raise RuntimeError("c358 route-0 day-zero contract drift")
        tape[step]["hands"][1] = command
    if tape[29]["hands"][2] != ["BUILD_PASTURE"]:
        raise RuntimeError("c358 route-0 day-one contract drift")
    tape[29]["hands"][2] = ["WATER"]
    commands = [
        ["WEST"], ["WEST"], ["WEST"], ["WATER"], ["HARVEST"],
        ["BUILD_PASTURE"], ["EAST"], ["EAST"], ["DROP"],
    ]
    for step, command in zip(range(49, 58), commands):
        if tape[step]["hands"][0] != ["PASS"]:
            raise RuntimeError("c358 route-0 day-two contract drift")
        tape[step]["hands"][0] = command
    if max(len(action.get("market", [])) for action in tape[:96]) > 10:
        raise RuntimeError("c358 market order overflow")


def _c358_sell_extra(action, item, quantity):
    if quantity <= 0:
        return action
    orders = [list(order) for order in action.get("market", [])]
    sell = next((order for order in orders
                 if len(order) >= 3 and order[:2] == ["SELL", item]), None)
    if sell is not None:
        sell[2] += quantity
    elif len(orders) < 10:
        orders.append(["SELL", item, quantity])
    else:
        return action
    return dict(action, market=orders)


def agent(observation, configuration=None):
    seat = int(observation["player"])
    step = int(observation["step"])
    state = _C358_STATE.get(seat)
    if state is None or step <= state["step"]:
        if _C358_ENABLED:
            _c358_install()
        state = _C358_STATE[seat] = {"step": -1}
        _C358_REPORT.clear()
        _C358_REPORT.update(
            temporary_crop_seen=0, temporary_crop_harvested=0,
            restored_pasture_seen=0, delivered_extra_wheat=0,
            extension_errors=0,
        )
    action = _C358_PARENT(observation, configuration)
    if _C358_ENABLED:
        try:
            farm = observation["farms"][seat]
            private = observation["private"]
            site = farm["tiles"][4][2]
            if step == 6:
                _C358_REPORT["temporary_crop_seen"] = int(
                    isinstance(site, dict) and site.get("crop") == "WHEAT")
            if step == 54:
                _C358_REPORT["temporary_crop_harvested"] = int(
                    private["inventories"][1].get("WHEAT", 0))
            if step == 55:
                _C358_REPORT["restored_pasture_seen"] = int(
                    isinstance(site, dict) and site.get("kind") == "PASTURE")
            if (step == 57 and len(farm["hands"]) >= 1
                    and tuple(farm["hands"][0]) == (4, 4)
                    and action.get("hands", [[]])[0] == ["DROP"]):
                quantity = int(private["inventories"][1].get("WHEAT", 0))
                action = _c358_sell_extra(action, "WHEAT", quantity)
                _C358_REPORT["delivered_extra_wheat"] = quantity
        except Exception:
            _C358_REPORT["extension_errors"] += 1
    state["step"] = step
    return action


agent.telemetry = _C358_REPORT
kaggle_submission_agent = agent
# c365: preserve c358 and change only the existing CARROT2 controller's
# feed-reserve horizon from two days to one. Public One More Wheat, Metav4,
# V54 and Pipe16 use the same one-day horizon. Integration: Taeyang/Codex, 2026.
_C365_ENABLED = True
_C365_PARENT = agent
_C365_REPORT = {}


def _c365_find_carrot_namespace(namespace):
    seen = set()
    while isinstance(namespace, dict) and id(namespace) not in seen:
        seen.add(id(namespace))
        if "_CA_FEED_DAYS" in namespace and "_CA_REPORT" in namespace:
            return namespace
        namespace = namespace.get("_BASE_NS")
    return None


_C365_CA_NS = _c365_find_carrot_namespace(globals())
if _C365_CA_NS is None:
    raise RuntimeError("c365 could not locate the CARROT2 controller")
_C365_PARENT_FEED_DAYS = _C365_CA_NS["_CA_FEED_DAYS"]
if _C365_PARENT_FEED_DAYS != 2:
    raise RuntimeError("c365 parent feed-reserve contract drift")


def agent(observation, configuration=None):
    _C365_CA_NS["_CA_FEED_DAYS"] = 1 if _C365_ENABLED else _C365_PARENT_FEED_DAYS
    action = _C365_PARENT(observation, configuration)
    report = _C365_CA_NS.get("_CA_REPORT", {})
    _C365_REPORT.clear()
    _C365_REPORT.update(
        enabled=int(_C365_ENABLED),
        feed_days=int(_C365_CA_NS["_CA_FEED_DAYS"]),
        ca_swaps=int(report.get("ca_swaps", 0)),
        ca_feed_block=int(report.get("ca_feed_block", 0)),
        ca_errors=int(report.get("ca_errors", 0)),
    )
    return action


agent.telemetry = _C365_REPORT
kaggle_submission_agent = agent
c365_submission_agent = agent


# c368: preserve c365's production decisions and one-day feed horizon.
# Once its chassis has irrevocably entered terminal route 2, a reserve larger
# than ALL remaining wheat/carrot planting commands cannot be consumed.
