# o301: opening hire cash floor. The native d0 plan ends with $1-12 and the d1
# HIRE orders cost fib(1,1,2,...). Live replays show three collapses (1-2 hands
# on d1, cows starve, -4k..-18k) when the d0 wheat round-trip left $1-3. When
# the parent's HIRE orders in the first days cannot all be paid, sell shed
# fertilizer, then wheat, for the shortfall only. A wheat sale can starve one
# morning FEED (the plan picks up every stored unit), so on that day a hand that
# is idle for the rest of its shift re-feeds the animal once the plan has bought
# wheat again. No plan edits, extra hires, purchases or land.
_O301_ENABLED = True
_O301_PARENT = agent
_O301_REPORT = {}
_O301_STATES = {}
_O301_ITEMS = ('FERTILIZER', 'WHEAT', 'EGG', 'CARROT', 'TOMATO', 'MELON', 'WOOL', 'MILK', 'STRAWBERRY')
_O301_MAX_DAY = 2
_O301_MAX_ORDERS = 10
_O301_SEED = {'WHEAT': 10, 'CARROT': 20, 'TOMATO': 50, 'STRAWBERRY': 100, 'MELON': 80}
_O301_ANIMAL = {'GOOSE': 300, 'COW': 400, 'SHEEP': 500}

def _o301_fib(n):
    a, b = 1, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def _o301_shortfall(observation, market):
    """Largest cash gap before any HIRE while replaying the order list in engine order."""
    farm = observation['farms'][int(observation['player'])]
    prices = observation['market']['prices']
    shed = dict(observation['private'].get('shed') or {})
    money = float(farm['money'])
    hires = int(farm.get('hires_today', 0))
    gap = 0.0
    for order in market:
        if not order:
            continue
        op = order[0]
        if op == 'HIRE':
            cost = _o301_fib(hires)
            gap = max(gap, cost - money)
            money -= cost
            hires += 1
        elif op == 'BUY_LAND':
            money -= 4000
        elif len(order) >= 3:
            item, qty = order[1], max(0, int(order[2]))
            if op == 'BUY_SEED':
                money -= qty * _O301_SEED.get(item, 100)
            elif op == 'BUY_ANIMAL':
                money -= qty * _O301_ANIMAL.get(item, 500)
            elif op == 'BUY_PRODUCT':
                money -= qty * (int(prices.get(item, 100)) + 2)
            elif op == 'SELL':
                units = min(qty, int(shed.get(item, 0)))
                shed[item] = int(shed.get(item, 0)) - units
                money += units * max(1, int(prices.get(item, 1)) - 2)
    return gap

def _o301_floor(observation, action, state):
    market = [list(o) for o in (action.get('market') or []) if o]
    if not any(o[0] == 'HIRE' for o in market) or len(market) >= _O301_MAX_ORDERS:
        return action
    _O301_REPORT['floor_checks'] += 1
    gap = _o301_shortfall(observation, market)
    if gap <= 0:
        return action
    prices = observation['market']['prices']
    shed = observation['private'].get('shed') or {}
    planned = {}
    for o in market:
        if o[0] == 'SELL' and len(o) >= 3:
            planned[o[1]] = planned.get(o[1], 0) + max(0, int(o[2]))
    extra = []
    for item in _O301_ITEMS:
        if gap <= 0:
            break
        free = int(shed.get(item, 0)) - planned.get(item, 0)
        unit = max(1, int(prices.get(item, 1)) - 2)
        if free <= 0 or unit < 3:
            continue
        units = min(free, -(-int(gap) // unit))
        extra.append(['SELL', item, units])
        gap -= units * unit
        if len(market) + len(extra) >= _O301_MAX_ORDERS:
            break
    if not extra:
        _O301_REPORT['floor_unfunded'] += 1
        return action
    if gap > 0:
        _O301_REPORT['floor_unfunded'] += 1
    action = dict(action)
    action['market'] = extra + market
    _O301_REPORT['floor_sales'] += 1
    _O301_REPORT['floor_units'] += sum(o[2] for o in extra)
    if any(o[1] == 'WHEAT' for o in extra):
        state['floor_day'] = int(observation['step']) // 24
    return action

def _o301_commands(action, count):
    commands = [list(action.get('farmer') or ['PASS'])] + [list(c) if c else ['PASS'] for c in (action.get('hands') or [])]
    commands += [['PASS'] for _ in range(count - len(commands))]
    return commands[:count]

def _o301_idle(route, actor, step):
    """True when the tape gives this actor nothing but PASS for the rest of the day."""
    tape = _C358_IMPL.chassis.routes[route]
    for t in range(step + 1, min(len(tape), (step // 24 + 1) * 24)):
        frame = tape[t] if isinstance(tape[t], dict) else {}
        if actor == 0:
            command = frame.get('farmer') or ['PASS']
        else:
            hands = frame.get('hands') or []
            command = hands[actor - 1] if actor - 1 < len(hands) else None
        if command is not None and list(command) != ['PASS']:
            return False
    return True

def _o301_walk(pos, target):
    x, y = pos; tx, ty = target
    if x != tx:
        return ['EAST' if x < tx else 'WEST']
    if y != ty:
        return ['SOUTH' if y < ty else 'NORTH']
    return None

def _o301_repair(observation, action, state):
    step = int(observation['step']); day = step // 24
    player = int(observation['player']); farm = observation['farms'][player]
    tiles = farm['tiles']; board = len(tiles); half = board // 2
    positions = [tuple(farm['farmer'])] + [tuple(p) for p in (farm.get('hands') or [])]
    inventories = list(observation['private'].get('inventories') or [])
    shed = observation['private'].get('shed') or {}
    commands = _o301_commands(action, len(positions))

    def animal_tile(target):
        x, y = target
        tile = tiles[y][x] if 0 <= y < board and 0 <= x < board else None
        return tile if isinstance(tile, dict) and tile.get('animal') else None

    # 1. Record FEED commands that cannot succeed because the worker carries no wheat.
    for actor, command in enumerate(commands):
        if command[0] != 'FEED' or actor >= len(positions):
            continue
        inv = inventories[actor] if actor < len(inventories) else {}
        tile = animal_tile(positions[actor])
        if tile is not None and not tile.get('fed_today') and int(inv.get('WHEAT', 0)) <= 0:
            if positions[actor] not in state['unfed']:
                state['unfed'].append(positions[actor])
                _O301_REPORT['feed_failures'] += 1
    # 2. Drop finished or stale jobs.
    for actor in list(state['jobs']):
        job = state['jobs'][actor]
        tile = animal_tile(job['target'])
        if actor >= len(positions) or tile is None or tile.get('fed_today') or commands[actor] != ['PASS']:
            if tile is not None and tile.get('fed_today'):
                _O301_REPORT['feed_repairs_done'] += 1
            state['jobs'].pop(actor)
    # 3. Assign unassigned targets to actors idle for the rest of the day.
    route = _C358_IMPL.chassis.players[player]['route']
    busy = {job['target'] for job in state['jobs'].values()}
    for target in list(state['unfed']):
        tile = animal_tile(target)
        if tile is None or tile.get('fed_today'):
            state['unfed'].remove(target)
            continue
        if target in busy:
            continue
        for actor in list(range(1, len(positions))) + [0]:
            if actor in state['jobs'] or commands[actor] != ['PASS'] or not _o301_idle(route, actor, step):
                continue
            state['jobs'][actor] = {'target': target}
            busy.add(target)
            _O301_REPORT['feed_repairs_assigned'] += 1
            break
    if not state['jobs']:
        return action
    # 4. Drive the jobs: fetch one wheat from the shed, walk to the animal, feed.
    for actor, job in state['jobs'].items():
        pos = positions[actor]; inv = inventories[actor] if actor < len(inventories) else {}
        target = job['target']
        if int(inv.get('WHEAT', 0)) > 0:
            command = _o301_walk(pos, target) or ['FEED']
        elif int(shed.get('WHEAT', 0)) > 0:
            if pos[0] in (half - 1, half) and pos[1] in (half - 1, half):
                command = ['PICKUP', 'WHEAT', 1]
            else:
                access = min(((half - 1, half - 1), (half, half - 1), (half - 1, half), (half, half)),
                             key=lambda p: abs(pos[0] - p[0]) + abs(pos[1] - p[1]))
                command = _o301_walk(pos, access) or ['PASS']
        else:
            command = ['PASS']
        commands[actor] = command
        _O301_REPORT['feed_repair_steps'] += 1
    action = dict(action)
    action['farmer'], action['hands'] = commands[0], commands[1:]
    return action

def agent(observation, configuration=None):
    action = _O301_PARENT(observation, configuration)
    step = int(observation['step']); day = step // 24; player = int(observation['player'])
    state = _O301_STATES.get(player)
    if step == 0 or state is None or step <= state['last_step']:
        state = {'last_step': step, 'floor_day': -1, 'day': -1, 'unfed': [], 'jobs': {}}
        _O301_STATES[player] = state
        _O301_REPORT.clear()
        _O301_REPORT.update(floor_checks=0, floor_sales=0, floor_units=0, floor_unfunded=0, feed_failures=0,
                            feed_repairs_assigned=0, feed_repairs_done=0, feed_repair_steps=0)
    state['last_step'] = step
    if state['day'] != day:
        state['day'] = day; state['unfed'] = []; state['jobs'] = {}
    _O301_REPORT.update(_C373_REPORT)
    if not _O301_ENABLED or day > _O301_MAX_DAY:
        return action
    action = _o301_floor(observation, action, state)
    if state['floor_day'] == day:
        action = _o301_repair(observation, action, state)
    return action

agent.telemetry = _O301_REPORT
kaggle_submission_agent = agent
o301_submission_agent = agent

# o302: farmer feed pickup top-up. In the route-0 family the day-26 tape has
# the farmer pick up one wheat at h1 but FEED at h5 and h17; when the h17 goose
# is still unfed the FEED fails and the goose escapes (17/118 live games, same
# for public-lineage rivals). When the farmer's PICKUP WHEAT carries fewer units
# than its remaining tape FEEDs today, raise the pickup by the deficit, bounded
# by shed stock left after every other pickup planned for the rest of the day.
# Hands are untouched; unused units return to the shed at midnight.
_O302_ENABLED = True
_O302_PARENT = agent
_O302_REPORT = {}

def _o302_frames(player, step):
    route = _C358_IMPL.chassis.players[player]['route']
    tape = _C358_IMPL.chassis.routes[route]
    return [tape[t] if isinstance(tape[t], dict) else {} for t in range(step + 1, min(len(tape), (step // 24 + 1) * 24))]

def _o302_topup(observation, action):
    farmer = list(action.get('farmer') or ['PASS'])
    if farmer[0] != 'PICKUP' or len(farmer) < 2 or farmer[1] != 'WHEAT':
        return action
    step = int(observation['step']); player = int(observation['player'])
    frames = _o302_frames(player, step)
    feeds = sum(1 for f in frames if (f.get('farmer') or ['PASS'])[0] == 'FEED')
    carried = int((observation['private'].get('inventories') or [{}])[0].get('WHEAT', 0))
    quantity = max(1, int(farmer[2])) if len(farmer) >= 3 else 1
    deficit = feeds - carried - quantity
    if deficit <= 0:
        return action
    shed = int((observation['private'].get('shed') or {}).get('WHEAT', 0))
    others = 0
    for c in (action.get('hands') or []):
        if c and c[0] == 'PICKUP' and len(c) >= 2 and c[1] == 'WHEAT':
            others += max(1, int(c[2])) if len(c) >= 3 else 1
    for f in frames:
        for c in [f.get('farmer')] + list(f.get('hands') or []):
            if c and c[0] == 'PICKUP' and len(c) >= 2 and c[1] == 'WHEAT':
                others += max(1, int(c[2])) if len(c) >= 3 else 1
    extra = min(deficit, shed - quantity - others)
    if extra <= 0:
        _O302_REPORT['topup_declined'] += 1
        return action
    action = dict(action)
    action['farmer'] = ['PICKUP', 'WHEAT', quantity + extra]
    _O302_REPORT['topups'] += 1
    _O302_REPORT['topup_units'] += extra
    return action

def agent(observation, configuration=None):
    action = _O302_PARENT(observation, configuration)
    if int(observation['step']) == 0:
        _O302_REPORT.clear()
        _O302_REPORT.update(topups=0, topup_units=0, topup_declined=0)
    _O302_REPORT.update(_O301_REPORT)
    if not _O302_ENABLED:
        return action
    return _o302_topup(observation, action)

agent.telemetry = _O302_REPORT
kaggle_submission_agent = agent
o302_submission_agent = agent

# o303: wheat fertilizer tour. Fertilized wheat harvests 5.7-5.8 units against
# 3.4-3.8 unfertilized (own ledgers), the tape leaves 12-19 unfertilized age-1/2
# wheat tiles every day from d14 to d25, and late fertilizer sells for $8-35.
# Each morning: if k = min(8, candidates, shed fertilizer) units withheld from the
# morning fertilizer sales, one extra hand (hired after every native hire so the
# tape's hand indices are untouched) and the wheat price clear a net floor,
# hire that hand, pick up k fertilizer and fertilize the nearest candidates.
# Nothing else in the plan changes; leftovers return to the shed at midnight.
_O303_ENABLED = True
_O303_PARENT = agent
_O303_REPORT = {}
_O303_STATES = {}
_O303_MAX_UNITS = 8
_O303_MIN_UNITS = 3
_O303_MIN_NET = 150.0
_O303_GAIN_PER_UNIT = 2.0
_O303_LAST_HARVEST_DAY = 29
_O303_MAX_ORDERS = 10
_O303_HIRE_DEADLINE = 6

def _o303_fib(n):
    a, b = 1, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def _o303_frames(player, step):
    route = _C358_IMPL.chassis.players[player]['route']
    tape = _C358_IMPL.chassis.routes[route]
    day_end = min(len(tape), (step // 24 + 1) * 24)
    return [tape[t] if isinstance(tape[t], dict) else {} for t in range(step // 24 * 24, day_end)], step % 24

def _o303_candidates(farm, day):
    out = []
    for y, row in enumerate(farm['tiles']):
        for x, tile in enumerate(row):
            if not (isinstance(tile, dict) and tile.get('crop') == 'WHEAT'):
                continue
            age = day - int(tile.get('planted_day', day))
            if age in (1, 2) and int(tile.get('fertilized_until_day', -1)) < day and int(tile['planted_day']) + 4 <= _O303_LAST_HARVEST_DAY:
                out.append((x, y))
    return out

def _o303_walk(pos, target):
    x, y = pos; tx, ty = target
    if x != tx:
        return ['EAST' if x < tx else 'WEST']
    if y != ty:
        return ['SOUTH' if y < ty else 'NORTH']
    return None

def _o303_plan(observation, state):
    """Decide the day's tour at h0 from candidates, shed stock, prices and the extra hire's cost."""
    step = int(observation['step']); day = step // 24; player = int(observation['player'])
    farm = observation['farms'][player]; prices = observation['market']['prices']
    frames, _ = _o303_frames(player, step)
    expected = max((len(f.get('hands') or []) for f in frames), default=0)
    candidates = _o303_candidates(farm, day)
    stock = int((observation['private'].get('shed') or {}).get('FERTILIZER', 0))
    units = min(_O303_MAX_UNITS, len(candidates), stock)
    hire_cost = _o303_fib(expected)
    net = units * _O303_GAIN_PER_UNIT * int(prices.get('WHEAT', 0)) - units * int(prices.get('FERTILIZER', 0)) - hire_cost
    state['plan'] = None
    if units < _O303_MIN_UNITS or net < _O303_MIN_NET:
        _O303_REPORT['tour_days_skipped'] += 1
        return
    state['plan'] = {'units': units, 'expected': expected, 'hired': False, 'actor': None, 'picked': False, 'done': 0, 'net': net}
    _O303_REPORT['tour_days_planned'] += 1

def _o303_withhold(observation, action, plan):
    """Keep the planned units out of this step's fertilizer sales until the hand has them."""
    stock = int((observation['private'].get('shed') or {}).get('FERTILIZER', 0))
    allowed = max(0, stock - plan['units'])
    market = [list(o) for o in (action.get('market') or []) if o]
    changed = False
    for o in market:
        if o[0] == 'SELL' and len(o) >= 3 and o[1] == 'FERTILIZER':
            q = max(0, int(o[2])); keep = min(q, allowed); allowed -= keep
            if keep != q:
                _O303_REPORT['withheld_units'] += q - keep; o[2] = keep; changed = True
    if changed:
        action = dict(action); action['market'] = [o for o in market if not (o[0] == 'SELL' and len(o) >= 3 and int(o[2]) <= 0)]
    return action

def _o303_hire(observation, action, plan):
    step = int(observation['step']); hour = step % 24; player = int(observation['player'])
    farm = observation['farms'][player]
    if hour > _O303_HIRE_DEADLINE:
        plan['hired'] = None; _O303_REPORT['hire_missed_deadline'] += 1
        return action
    frames, offset = _o303_frames(player, step)
    if any(o and o[0] == 'HIRE' for f in frames[offset + 1:] for o in (f.get('market') or [])):
        return action
    market = [list(o) for o in (action.get('market') or []) if o]
    parent_hires = sum(1 for o in market if o[0] == 'HIRE')
    if len(farm['hands']) + parent_hires != plan['expected'] or len(market) >= _O303_MAX_ORDERS:
        plan['hired'] = None; _O303_REPORT['hire_skipped_indices'] += 1
        return action
    cost = _o303_fib(int(farm.get('hires_today', 0)) + parent_hires)
    if float(farm['money']) < cost + 1000:
        plan['hired'] = None; _O303_REPORT['hire_skipped_cash'] += 1
        return action
    action = dict(action); action['market'] = market + [['HIRE']]
    plan['hired'] = True; plan['actor'] = plan['expected'] + 1; plan['hire_step'] = step
    _O303_REPORT['tour_hires'] += 1
    return action

def _o303_tour(observation, action, plan):
    step = int(observation['step']); day = step // 24; player = int(observation['player'])
    farm = observation['farms'][player]; actor = plan['actor']
    hands = farm.get('hands') or []
    if actor - 1 >= len(hands):
        if step == plan.get('hire_step', -1) + 1:
            plan['hired'] = None; _O303_REPORT['hire_shortfalls'] += 1
        return action
    pos = tuple(hands[actor - 1]); board = len(farm['tiles']); half = board // 2
    inventories = observation['private'].get('inventories') or []
    inv = inventories[actor] if actor < len(inventories) else {}
    carried = int(inv.get('FERTILIZER', 0))
    shed = int((observation['private'].get('shed') or {}).get('FERTILIZER', 0))
    adjacent = pos[0] in (half - 1, half) and pos[1] in (half - 1, half)
    command = ['PASS']
    if not plan['picked']:
        if adjacent:
            units = min(plan['units'], shed)
            if units > 0:
                command = ['PICKUP', 'FERTILIZER', units]; plan['picked'] = True; _O303_REPORT['picked_units'] += units
            else:
                plan['picked'] = True; _O303_REPORT['pickup_empty'] += 1
        else:
            access = min(((half - 1, half - 1), (half, half - 1), (half - 1, half), (half, half)),
                         key=lambda p: abs(pos[0] - p[0]) + abs(pos[1] - p[1]))
            command = _o303_walk(pos, access) or ['PASS']
    elif carried > 0:
        targets = _o303_candidates(farm, day)
        if targets:
            target = min(targets, key=lambda p: (abs(pos[0] - p[0]) + abs(pos[1] - p[1]), p))
            command = _o303_walk(pos, target) or ['FERTILIZE']
            if command == ['FERTILIZE']:
                plan['done'] += 1; _O303_REPORT['fertilizations'] += 1
        else:
            _O303_REPORT['idle_steps'] += 1
    else:
        _O303_REPORT['idle_steps'] += 1
    commands = [list(action.get('farmer') or ['PASS'])] + [list(c) if c else ['PASS'] for c in (action.get('hands') or [])]
    commands += [['PASS'] for _ in range(len(hands) + 1 - len(commands))]
    commands[actor] = command
    action = dict(action); action['farmer'], action['hands'] = commands[0], commands[1:]
    return action

def agent(observation, configuration=None):
    action = _O303_PARENT(observation, configuration)
    step = int(observation['step']); day = step // 24; player = int(observation['player'])
    state = _O303_STATES.get(player)
    if step == 0 or state is None or step <= state['last_step']:
        state = {'last_step': step, 'day': -1, 'plan': None}
        _O303_STATES[player] = state
        _O303_REPORT.clear()
        _O303_REPORT.update(tour_days_planned=0, tour_days_skipped=0, tour_hires=0, hire_missed_deadline=0, hire_skipped_indices=0,
                            hire_skipped_cash=0, hire_shortfalls=0, withheld_units=0, picked_units=0, pickup_empty=0,
                            fertilizations=0, idle_steps=0)
    state['last_step'] = step
    _O303_REPORT.update(_O302_REPORT)
    if not _O303_ENABLED:
        return action
    if state['day'] != day:
        state['day'] = day
        _o303_plan(observation, state)
    plan = state['plan']
    if not plan or plan['hired'] is None:
        return action
    if not plan['picked']:
        action = _o303_withhold(observation, action, plan)
    if not plan['hired']:
        return _o303_hire(observation, action, plan)
    return _o303_tour(observation, action, plan)

agent.telemetry = _O303_REPORT
kaggle_submission_agent = agent
o303_submission_agent = agent
